
/* XLSX offline stub - implements only features used in this app */
const XLSX = (function() {
  'use strict';

  function aoa_to_sheet(data) {
    const ws = {};
    const range = {s:{c:0,r:0}, e:{c:0,r:0}};
    data.forEach((row, R) => {
      if (R > range.e.r) range.e.r = R;
      row.forEach((cell, C) => {
        if (C > range.e.c) range.e.c = C;
        const addr = encode_cell({r:R, c:C});
        ws[addr] = { v: cell, t: typeof cell === 'number' ? 'n' : 's' };
      });
    });
    ws['!ref'] = encode_range(range);
    return ws;
  }

  function encode_cell(cell) {
    let col = '';
    let c = cell.c;
    for (let i = 0; i >= 0; i--) {
      col = String.fromCharCode(65 + (c % 26)) + col;
      c = Math.floor(c / 26) - 1;
      if (c < 0) break;
    }
    return col + (cell.r + 1);
  }

  function encode_range(range) {
    return encode_cell(range.s) + ':' + encode_cell(range.e);
  }

  function book_new() {
    return { SheetNames: [], Sheets: {} };
  }

  function book_append_sheet(wb, ws, name) {
    wb.SheetNames.push(name);
    wb.Sheets[name] = ws;
  }

  function writeFile(wb, filename) {
    // Build CSV-like content, then save as .xlsx OOXML
    const sheetName = wb.SheetNames[0];
    const ws = wb.Sheets[sheetName];
    const ref = ws['!ref'] || 'A1';
    const range = decode_range(ref);

    // Build simple XML for xlsx
    const rows = [];
    for (let R = range.s.r; R <= range.e.r; R++) {
      const cells = [];
      for (let C = range.s.c; C <= range.e.c; C++) {
        const addr = encode_cell({r:R, c:C});
        const cell = ws[addr];
        const val = cell ? String(cell.v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') : '';
        cells.push(`<c r="${addr}" t="inlineStr"><is><t>${val}</t></is></c>`);
      }
      rows.push(`<row r="${R+1}">${cells.join('')}</row>`);
    }

    const sheetXml = `<?xml version="1.0" encoding="UTF-8"?>\n<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${rows.join('')}</sheetData></worksheet>`;
    const wbXml = `<?xml version="1.0" encoding="UTF-8"?>\n<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="${sheetName}" sheetId="1" r:id="rId1"/></sheets></workbook>`;
    const relsXml = `<?xml version="1.0" encoding="UTF-8"?>\n<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>`;
    const wbRelsXml = `<?xml version="1.0" encoding="UTF-8"?>\n<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`;
    const contentXml = `<?xml version="1.0" encoding="UTF-8"?>\n<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>`;

    // Use JSZip if available, else fallback to CSV download
    if (typeof JSZip !== 'undefined') {
      const zip = new JSZip();
      zip.file('[Content_Types].xml', contentXml);
      zip.file('_rels/.rels', wbRelsXml);
      zip.file('xl/workbook.xml', wbXml);
      zip.file('xl/_rels/workbook.xml.rels', relsXml);
      zip.file('xl/worksheets/sheet1.xml', sheetXml);
      zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}).then(blob => {
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = filename;
        a.click();
      });
    } else {
      // Fallback: download as CSV
      const csvRows = [];
      for (let R = range.s.r; R <= range.e.r; R++) {
        const cells = [];
        for (let C = range.s.c; C <= range.e.c; C++) {
          const addr = encode_cell({r:R, c:C});
          const cell = ws[addr];
          cells.push(cell ? '"' + String(cell.v).replace(/"/g,'""') + '"' : '');
        }
        csvRows.push(cells.join(','));
      }
      const blob = new Blob(['\uFEFF' + csvRows.join('\n')], {type:'text/csv;charset=utf-8'});
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = filename.replace('.xlsx', '.csv');
      a.click();
    }
  }

  function decode_range(ref) {
    const parts = ref.split(':');
    return { s: decode_cell(parts[0]), e: decode_cell(parts[1] || parts[0]) };
  }

  function decode_cell(addr) {
    let c = 0, r = 0, i = 0;
    while (i < addr.length && addr[i] >= 'A') {
      c = c * 26 + (addr.charCodeAt(i) - 64);
      i++;
    }
    r = parseInt(addr.slice(i)) - 1;
    return { c: c - 1, r };
  }

  return {
    utils: { aoa_to_sheet, book_new, book_append_sheet },
    writeFile
  };
})();
